def exercise_missing_event_poll_fallback(
    container: LiveContainer,
    api: ApiClient,
) -> None:
    ready = "/run/user/1000/phase5-silent-event.ready"
    trigger = "/run/user/1000/phase5-silent-event.trigger"
    complete = "/run/user/1000/phase5-silent-event.complete"
    original_name = "Phase5 Silent Event Source"
    changed_name = "Phase5 Silent Event Changed"
    container.exec("rm", "-f", trigger, complete, user=1000, check=False)
    container.launch(
        (
            f"{FIXTURE_ROOT}/phase5-atspi-stress.py",
            "--nodes",
            "64",
            "--depth",
            "8",
            "--silent-name-trigger-file",
            trigger,
            "--silent-name-complete-file",
            complete,
            "--ready-file",
            ready,
        ),
        window_title="Xenoteer Phase5 AT-SPI Stress — Main",
        ready_file=ready,
    )
    reference: dict[str, Any] | None = None
    try:
        initial_entry = api.wait_name(original_name, timeout=30)
        require(initial_entry is not None, "missing-event source was absent")
        reference = element_reference(initial_entry)
        initial_snapshot = element_snapshot(api.snapshot_reference(reference))
        require(
            initial_snapshot.get("name") == original_name,
            "missing-event source did not start with its stable cached name",
        )
        container.exec("touch", trigger, user=1000)
        completion_deadline = time.monotonic() + 5
        while time.monotonic() < completion_deadline:
            if container.exec(
                "test", "-s", complete, user=1000, check=False, timeout=3
            ).returncode == 0:
                break
            time.sleep(0.05)
        else:
            raise AcceptanceError(
                "fixture did not complete its controlled silent name change"
            )

        # The toolkit's actual Accessible.Name has changed, but its frozen
        # GObject notification deliberately omitted the corresponding AT-SPI
        # PropertyChange event. Prove both sides before starting the waiter, so
        # poll_fallback_used cannot be attributed to a race with a real event.
        stale_snapshot = element_snapshot(api.snapshot_reference(reference))
        require(
            stale_snapshot.get("name") == original_name,
            "controlled missing-event mutation unexpectedly reached the event mirror",
        )
        require_central_atspi_name(container, reference, changed_name)

        wait_started = time.monotonic()
        wait_http_status, wait_result = api.wait_reference_name(
            reference,
            changed_name,
        )
        wait_elapsed = time.monotonic() - wait_started
        elements = wait_result.get("elements")
        require(
            wait_http_status == 200
            and wait_result.get("status") == "matched"
            and wait_result.get("predicate_satisfied") is True
            and wait_result.get("matched_count") == 1
            and wait_result.get("poll_fallback_used") is True
            and wait_result.get("truncated") is False
            and is_integer(wait_result.get("evaluated_revision"), minimum=1)
            and isinstance(elements, list)
            and len(elements) == 1
            and wait_elapsed <= 6,
            "controlled missing accessibility event did not recover through a bounded poll",
        )
        waited_entry = elements[0]
        require(
            isinstance(waited_entry, dict)
            and element_snapshot(waited_entry).get("name") == changed_name,
            "poll fallback did not return the reconciled toolkit property",
        )
    finally:
        container.stop("phase5-atspi-stress.py")
        container.exec(
            "rm",
            "-f",
            trigger,
            complete,
            user=1000,
            check=False,
        )
    if reference is not None:
        api.require_ref_rejected(reference)


def exercise_stress_and_reconnect(container: LiveContainer, api: ApiClient) -> None:
    # Establish control before the intentionally large accessibility surface
    # can transiently degrade optional viewer readiness. The controller lease
    # and raw input plane must remain usable throughout that optional pressure.
    api.wait_desktop_ready(timeout=30)
    session = CommandSession(api)
    session.connect()
    ready = "/run/user/1000/phase5-stress.ready"
    command = (
        f"{FIXTURE_ROOT}/phase5-atspi-stress.py",
        "--nodes",
        "4096",
        "--depth",
        "48",
        "--ready-file",
        ready,
    )
    container.launch(
        command,
        window_title="Xenoteer Phase5 AT-SPI Stress — Main",
        ready_file=ready,
    )
    for name in (
        "Phase5 Stable Button",
        "Phase5 Incomplete Custom Canvas",
        "Phase5 Large Materialized List",
        "Phase5 Deep Tree",
        "Phase5 Malformed Self Relation",
    ):
        require(api.wait_name(name, timeout=60) is not None, f"{name} was absent")
    large_names, large_pages = api.collect_name_prefix("Phase5 Large Row 04")
    require(
        large_pages >= 4
        and len(large_names) == 96
        and large_names[0] == "Phase5 Large Row 04000"
        and large_names[-1] == "Phase5 Large Row 04095",
        "large accessibility query did not traverse its stable cursor to the final row; "
        f"pages={large_pages} count={len(large_names)} "
        f"first={large_names[0] if large_names else None!r} "
        f"last={large_names[-1] if large_names else None!r}",
    )
    old_entry = api.wait_name("Phase5 Stable Button")
    require(old_entry is not None, "stress fixture stable button was absent")
    old_reference = element_reference(old_entry)
    canvas_entry = api.wait_name("Phase5 Incomplete Custom Canvas", timeout=30)
    require(canvas_entry is not None, "custom canvas component evidence was absent")
    canvas_reference = element_reference(canvas_entry)
    canvas_entry = api.snapshot_reference(canvas_reference, component=True)
    canvas_snapshot = element_snapshot(canvas_entry)
    canvas_extents = require_atspi_component(
        canvas_snapshot, "custom canvas public query"
    )
    canvas_center = {
        "x": canvas_extents["x"] + canvas_extents["width"] // 2,
        "y": canvas_extents["y"] + canvas_extents["height"] // 2,
        "width": 1,
        "height": 1,
    }
    wait_http_status, geometry_wait = api.wait_reference_geometry(
        canvas_reference,
        canvas_center,
    )
    require(
        wait_http_status == 200
        and geometry_wait.get("status") == "matched"
        and geometry_wait.get("predicate_satisfied") is True
        and geometry_wait.get("matched_count") == 1
        and geometry_wait.get("poll_fallback_used") is False
        and geometry_wait.get("truncated") is False
        and is_integer(geometry_wait.get("evaluated_revision"), minimum=1),
        "custom canvas public geometry wait did not match deterministically",
    )
    waited_elements = geometry_wait.get("elements")
    require(
        isinstance(waited_elements, list) and len(waited_elements) == 1,
        "custom canvas public geometry wait did not return exactly one element",
    )
    waited_entry = waited_elements[0]
    require(
        isinstance(waited_entry, dict),
        "custom canvas public geometry wait returned a malformed element",
    )
    waited_snapshot = element_snapshot(waited_entry)
    require(
        waited_snapshot.get("ref") == canvas_reference,
        "custom canvas public geometry wait changed element identity",
    )
    waited_extents = require_atspi_component(
        waited_snapshot, "custom canvas public geometry wait"
    )
    require(
        rects_intersect(waited_extents, canvas_center),
        "custom canvas public geometry wait returned non-intersecting extents",
    )
    stress_window = api.resolve_window_reference(
        "Xenoteer Phase5 AT-SPI Stress — Main"
    )
    desktop_generation = api.generation
    previous_bus_pid = ""
    try:
        for attempt in range(3):
            latest_canvas = api.wait_name("Phase5 Incomplete Custom Canvas", timeout=30)
            require(latest_canvas is not None, "custom canvas disappeared before invocation")
            canvas_reference = element_reference(latest_canvas)
            api.snapshot_reference(canvas_reference, component=True)
            try:
                session.submit(
                    {
                        "type": "element_invoke",
                        "element": canvas_reference,
                        "action": {"type": "default"},
                        "allow_disabled": False,
                        "postcondition": None,
                    },
                    timeout=15,
                )
            except CommandFailure as error:
                if (
                    error.code
                    in {"interface_not_supported", "unsupported_by_target"}
                    and error.effect == "none"
                ):
                    break
                if (
                    error.code == "stale_reference"
                    and error.effect == "none"
                    and attempt < 2
                ):
                    continue
                raise AcceptanceError(
                    "semantic invocation of custom canvas was not rejected safely; "
                    f"code={error.code} effect={error.effect} retry={error.retry}"
                ) from error
            else:
                raise AcceptanceError("semantic invocation of custom canvas unexpectedly succeeded")
        activated = session.submit(
            {
                "type": "window_activate",
                "window": stress_window,
                "switch_workspace": True,
                "fallback": "ewmh_only",
            }
        )
        require(
            activated.get("effect_stage") == "window_state_changed",
            "custom-canvas window activation did not converge",
        )
        physical_canvas = session.submit(
            {
                "type": "element_physical_click",
                "element": canvas_reference,
                "window": stress_window,
                "minimum_correlation": "strong",
                "point_policy": {"type": "center"},
                "scroll_policy": "if_needed",
                "activation_policy": "if_needed",
                "occlusion_policy": "ignore",
                "button": "left",
                "count": 1,
                "interval_ms": 0,
                "move_duration_ms": 150,
                "curve": "smooth",
                "settle_timeout_ms": 5_000,
                "postcondition": None,
            },
            timeout=45,
        )
        require_physical_result(
            physical_canvas,
            canvas_reference,
            stress_window,
            "custom canvas after semantic rejection",
        )
        previous_bus_pid = container.stop_atspi_bus()
        api.wait_accessibility_unavailable()
        deadline = time.monotonic() + 15
        last_snapshot_status = 200
        while time.monotonic() < deadline:
            last_snapshot_status = api.snapshot_status(old_reference)
            if last_snapshot_status in {409, 503}:
                break
            time.sleep(0.1)
        require(
            last_snapshot_status in {409, 503},
            "accessibility reads did not fail closed while the AT-SPI bus was down",
        )
        require_no_effect_command_rejected(
            session,
            {
                "type": "element_invoke",
                "element": old_reference,
                "action": {"type": "default"},
                "allow_disabled": False,
                "postcondition": None,
            },
            {"capability_unavailable", "stale_reference", "toolkit_protocol_error"},
            "semantic command during AT-SPI degradation",
        )
        raw_result = session.submit(
            {
                "type": "pointer_move",
                "target": {"x": 32, "y": 32},
                "duration_ms": 100,
                "curve": "smooth",
            }
        )
        require(
            raw_result.get("effect_stage") == "pointer_moved",
            "raw physical input stopped when optional accessibility degraded",
        )
    finally:
        if previous_bus_pid:
            container.start_atspi_bus(previous_bus_pid)
        session.close()
    api.wait_accessibility_available(timeout=60)
    # Some toolkit bridges retain their connection to the dead accessibility
    # bus for the lifetime of the process and therefore do not re-register on
    # a replacement bus. That is toolkit behavior, not evidence that the daemon
    # failed to reconnect. First prove the old reference is fenced, then launch
    # a fresh client on the replacement bus and prove new references work.
    api.require_ref_rejected(old_reference)
    container.stop("phase5-atspi-stress.py")
    api.wait_name("Phase5 Stable Button", present=False)
    container.launch(
        (
            f"{FIXTURE_ROOT}/phase5-atspi-stress.py",
            "--nodes",
            "64",
            "--depth",
            "8",
            "--ready-file",
            ready,
        ),
        window_title="Xenoteer Phase5 AT-SPI Stress — Main",
        ready_file=ready,
    )
    new_entry = api.wait_name_with_new_ref(
        "Phase5 Stable Button", old_reference, timeout=75
    )
    new_reference = element_reference(new_entry)
    require(
        new_reference["atspi_generation"] != old_reference["atspi_generation"],
        "AT-SPI reconnect did not advance the AT-SPI generation fence",
    )
    api.discover()
    require(api.generation == desktop_generation, "AT-SPI reconnect changed desktop lifetime")
    container.stop("phase5-atspi-stress.py")
    api.wait_name("Phase5 Stable Button", present=False)


def exercise_deep_budget(container: LiveContainer, api: ApiClient) -> None:
    ready = "/run/user/1000/phase5-deep.ready"
    container.launch(
        (
            f"{FIXTURE_ROOT}/phase5-atspi-stress.py",
            "--nodes",
            "64",
            "--depth",
            "24",
            "--ready-file",
            ready,
        ),
        window_title="Xenoteer Phase5 AT-SPI Stress — Main",
        ready_file=ready,
    )
    require(
        api.wait_name("Phase5 Deep Tree", timeout=60) is not None,
        "deep fixture did not reach the accessibility mirror",
    )
    # Keep the fixture within the actor's authoritative topology budget, then
    # give this query a deliberately smaller traversal budget. This isolates a
    # public query-budget failure from an actor-level malformed-tree rejection.
    status, problem = api.query_name_once(
        "Phase5 Deep Node 023", max_visited_nodes=25_000, max_depth=8
    )
    require(
        status == 422 and problem.get("code") == "query_budget_exceeded",
        "deep traversal did not fail closed at the declared query depth budget; "
        f"HTTP={status} code={problem.get('code')!r}",
    )
    api.status(timeout=5)
    container.stop("phase5-atspi-stress.py")


def subscribe_events(
    ws: ModuleType, client: Any, api: ApiClient, topics: list[str]
) -> str:
    request_id = ws.new_id()
    client.send_json(
        {
            "type": "events.subscribe",
            "request_id": request_id,
            "desktop_id": api.desktop_id,
            "desktop_generation": api.generation,
            "topics": topics,
            "since_sequence": None,
        }
    )
    subscribed = ws.expect_message(client, "events.subscribed", request_id)
    require(subscribed.get("topics") == topics, "event subscription topics changed")
    replay = ws.expect_message(client, "events.replay_complete", request_id)
    require(
        replay.get("desktop_id") == api.desktop_id
        and replay.get("desktop_generation") == api.generation
        and is_integer(replay.get("through_sequence")),
        "event replay boundary identity or sequence was invalid",
    )
    return request_id


def wait_flood_resync(
    ws: ModuleType,
    client: Any,
    subscription_id: str,
    api: ApiClient,
) -> tuple[str, int]:
    deadline = time.monotonic() + 30
    count = 0
    last_sequence = 0
    while time.monotonic() < deadline:
        message = client.recv(max(0.1, deadline - time.monotonic()))
        require(isinstance(message, dict), "event connection closed before a resync barrier")
        require(
            message.get("request_id") == subscription_id,
            "event flood produced an unrelated application message",
        )
        if message.get("type") == "events.resync_required":
            dropped = message.get("dropped_through")
            latest = message.get("latest_sequence")
            require(
                message.get("desktop_id") == api.desktop_id
                and message.get("desktop_generation") == api.generation
                and message.get("reason")
                in {"history_lost", "subscriber_lag", "outbound_backpressure"}
                and is_integer(dropped, minimum=1)
                and is_integer(latest, minimum=1)
                and dropped <= latest,
                "transport resync barrier did not match the closed protocol shape",
            )
            return "transport", count
        require(message.get("type") == "event", "event flood returned an unknown message")
        event = message.get("event")
        require(isinstance(event, dict), "event flood omitted its sequence envelope")
        sequence = event.get("sequence")
        require(
            is_integer(sequence, minimum=1)
            and sequence > last_sequence
            and event.get("desktop_id") == api.desktop_id
            and event.get("desktop_generation") == api.generation,
            "event flood sequence or desktop identity was invalid",
        )
        last_sequence = sequence
        count += 1
        require(count <= 100_000, "event flood exceeded its drain bound")
        if event.get("topic") == "accessibility.resync_required":
            payload = event.get("payload")
            require(isinstance(payload, dict), "accessibility resync payload was absent")
            require(
                payload.get("kind") == "resync_required"
                and payload.get("resync_reason")
                in {
                    "event_queue_overflow",
                    "actor_signal",
                    "generation_changed",
                    "event_gap",
                },
                "accessibility resync payload used an unknown reason",
            )
            require(
                payload.get("desktop_id") == api.desktop_id
                and payload.get("desktop_generation") == api.generation
                and is_integer(payload.get("atspi_generation"), minimum=1)
                and is_integer(payload.get("revision"), minimum=1)
                and is_integer(payload.get("cache_sequence"), minimum=1),
                "accessibility resync payload identity or revision was invalid",
            )
            return "accessibility", count
    raise AcceptanceError("event flood did not produce a fail-closed resync barrier")


def exercise_event_flood(container: LiveContainer, api: ApiClient) -> None:
    ws = load_websocket_client()
    slow_client = ws.WebSocket(api.base_url, TOKEN_CANARY)
    fast_client = ws.WebSocket(api.base_url, TOKEN_CANARY)
    ready = "/run/user/1000/phase5-flood.ready"
    trigger = "/run/user/1000/phase5-flood.trigger"
    complete = "/run/user/1000/phase5-flood.complete"
    try:
        container.exec("rm", "-f", trigger, complete, user=1000, check=False)
        container.launch(
            (
                f"{FIXTURE_ROOT}/phase5-atspi-stress.py",
                "--nodes",
                "256",
                "--depth",
                "16",
                "--event-burst",
                "5000",
                "--event-trigger-file",
                trigger,
                "--event-complete-file",
                complete,
                "--ready-file",
                ready,
            ),
            window_title="Xenoteer Phase5 AT-SPI Stress — Main",
            ready_file=ready,
        )
        stable_entry = api.wait_name("Phase5 Stable Button", timeout=30)
        require(stable_entry is not None, "flood fixture was absent")
        stable_reference = element_reference(stable_entry)
        # Subscribe only after the fixture launch/rebuild has settled so the
        # first observed continuity barrier is attributable to the flood.
        api.wait_desktop_ready(timeout=60)
        slow_client.connect()
        fast_client.connect()
        ws.hello(slow_client, api.desktop_id, api.generation)
        ws.hello(fast_client, api.desktop_id, api.generation)
        slow_subscription_id = subscribe_events(ws, slow_client, api, [])
        fast_subscription_id = subscribe_events(
            ws, fast_client, api, ["accessibility.resync_required"]
        )
        slow_client.set_receive_buffer(4096)
        container.exec("touch", trigger, user=1000)
        kind, _ = wait_flood_resync(
            ws, fast_client, fast_subscription_id, api
        )
        require(
            kind == "accessibility",
            "event flood did not surface actor-ingestion loss to a fast subscriber",
        )
        api.status(timeout=5)
        slow_kind, _ = wait_flood_resync(
            ws, slow_client, slow_subscription_id, api
        )
        require(
            slow_kind in {"transport", "accessibility"},
            "slow event subscriber did not receive a continuity boundary",
        )
        completion_deadline = time.monotonic() + 30
        while time.monotonic() < completion_deadline:
            if container.exec(
                "test", "-s", complete, user=1000, check=False, timeout=4
            ).returncode == 0:
                break
            time.sleep(0.1)
        else:
            raise AcceptanceError("fixture did not finish its bounded event flood")
        api.wait_accessibility_available(timeout=60)
        api.require_ref_rejected(stable_reference)
        # A toolkit process that was actively emitting while the connection
        # generation changed may keep its dead bridge connection. Restart that
        # controlled producer and prove a fresh client is ingested after loss.
        container.stop("phase5-atspi-stress.py")
        api.wait_name("Phase5 Stable Button", present=False)
        container.launch(
            (
                f"{FIXTURE_ROOT}/phase5-atspi-stress.py",
                "--nodes",
                "64",
                "--depth",
                "8",
                "--ready-file",
                ready,
            ),
            window_title="Xenoteer Phase5 AT-SPI Stress — Main",
            ready_file=ready,
        )
        api.wait_name_with_new_ref(
            "Phase5 Stable Button", stable_reference, timeout=60
        )
        api.status(timeout=5)
    finally:
        fast_client.close_transport()
        slow_client.close_transport()
        container.stop("phase5-atspi-stress.py")
    container.assert_healthy_limits()


def exercise_malformed_fixture(container: LiveContainer, api: ApiClient) -> None:
    ready = "/run/user/1000/phase5-malformed.ready"
    container.launch(
        (
            f"{FIXTURE_ROOT}/phase5-atspi-stress.py",
            "--nodes",
            "64",
            "--depth",
            "8",
            "--oversized-name-bytes",
            "70000",
            "--ready-file",
            ready,
        ),
        window_title="Xenoteer Phase5 AT-SPI Stress — Main",
        ready_file=ready,
    )
    api.status(timeout=5)
    # The finite cyclic relation and over-limit name may degrade this one
    # application, but neither is allowed to wedge the daemon or poison a
    # healthy sibling application while the offender remains connected.
    deadline = time.monotonic() + 3
    while time.monotonic() < deadline:
        api.status(timeout=5)
        time.sleep(0.25)
    container.launch(
        (f"{FIXTURE_ROOT}/gtk3-fixture.py",),
        window_title="Xenoteer GTK3 Fixture — Main",
    )
    require(
        api.wait_name("Xenoteer GTK3 Main Window", timeout=60) is not None,
        "malformed accessibility application poisoned a healthy sibling",
    )
    require(
        api.wait_name("Stable Button", timeout=30) is not None,
        "healthy sibling tree was unusable while malformed application remained",
    )
    container.stop("gtk3-fixture.py")
    api.wait_name("Xenoteer GTK3 Main Window", present=False)
    container.stop("phase5-atspi-stress.py")
    api.status(timeout=5)


def ensure_host_requirements() -> None:
    require(shutil.which("docker") is not None, "required host command is unavailable: docker")
    if os.geteuid() != 0:
        security = docker("info", "--format", "{{json .SecurityOptions}}").stdout
        require(
            "rootless" in security,
            "run as root or use rootless Docker for safe token-file ownership",
        )


def verify_image(image_reference: str) -> str:
    image = docker(
        "image", "inspect", image_reference, "--format", "{{.Id}}"
    ).stdout.strip()
    require(
        image.startswith("sha256:") and len(image) == 71,
        "fixture image did not resolve to an immutable image ID",
    )
    label = docker(
        "image",
        "inspect",
        image,
        "--format",
        '{{index .Config.Labels "com.aeor.xenoteer.fixture"}}',
    ).stdout.strip()
    require(label == "phase-2-desktop-apps", "image is not the desktop fixture layer")
    base = docker(
        "image",
        "inspect",
        image,
        "--format",
        '{{index .Config.Labels "com.aeor.xenoteer.fixture.base-image-id"}}',
    ).stdout.strip()
    require(
        base.startswith("sha256:") and len(base) == 71,
        "fixture image omitted its immutable base image label",
    )
    inspected = docker("image", "inspect", base, image).stdout
    try:
        base_value, fixture_value = json.loads(inspected)
    except (ValueError, TypeError) as error:
        raise AcceptanceError("Docker returned malformed image metadata") from error
    require(
        base_value.get("Id") == base and fixture_value.get("Id") == image,
        "image identity changed during fixture verification",
    )
    base_layers = base_value.get("RootFS", {}).get("Layers")
    fixture_layers = fixture_value.get("RootFS", {}).get("Layers")
    require(
        isinstance(base_layers, list)
        and isinstance(fixture_layers, list)
        and fixture_layers[: len(base_layers)] == base_layers,
        "fixture image does not preserve its recorded base layer prefix",
    )
    return image


def main() -> int:
    if len(sys.argv) > 2:
        raise AcceptanceError("usage: test-phase5-atspi-live.py [DESKTOP_APPS_IMAGE]")
    ensure_host_requirements()
    reference = (
        sys.argv[1]
        if len(sys.argv) == 2
        else os.environ.get("XENOTEER_DESKTOP_APPS_IMAGE", "xenoteer:desktop-apps-test")
    )
    image = verify_image(reference)
    with tempfile.TemporaryDirectory(prefix="xenoteer-phase5-atspi-") as temporary:
        token_file = Path(temporary) / "api-token"
        token_file.write_bytes(TOKEN_CANARY)
        token_file.chmod(0o400)
        container = LiveContainer(image, token_file)
        try:
            container.start()
            container.wait_desktop()
            base_url = f"http://127.0.0.1:{container.api_port()}"
            wait_public_ready(base_url, container)
            container.require_fixtures()
            api = ApiClient(base_url, TOKEN_CANARY)
            api.discover()
            api.wait_accessibility_available()

            exercise_restart(
                container,
                api,
                command=(f"{FIXTURE_ROOT}/gtk3-fixture.py",),
                title="Xenoteer GTK3 Fixture — Main",
                name="Stable Button",
                stop_pattern="gtk3-fixture.py",
                toolkit="GTK3",
                require_selection=False,
            )
            exercise_restart(
                container,
                api,
                command=(f"{FIXTURE_ROOT}/qt6-fixture.py",),
                title="Xenoteer Qt6 Fixture — Main",
                name="Stable Button",
                stop_pattern="qt6-fixture.py",
                toolkit="Qt6",
                require_selection=True,
            )
            exercise_chromium_reload(container, api)
            exercise_firefox_reload(container, api)
            exercise_missing_event_poll_fallback(container, api)
            exercise_stress_and_reconnect(container, api)
            exercise_deep_budget(container, api)
            exercise_event_flood(container, api)
            exercise_malformed_fixture(container, api)
            container.assert_logs_are_safe()
            container.assert_healthy_limits()
        except Exception:
            logs = container.safe_logs()
            if logs:
                print(logs, file=sys.stderr)
            raise
        finally:
            container.remove()
    print(
        "phase5 AT-SPI live gate passed: GTK/Qt restart fencing, "
        "Chromium/Firefox reload, private-P2P denial, missing-event poll recovery, "
        "large/deep/custom surfaces, oversized-input isolation, unit-tested topology "
        "defenses, bus reconnect, and bounded event flood"
    )
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (AcceptanceError, subprocess.TimeoutExpired, OSError) as error:
        print(f"phase5 AT-SPI live gate failed: {error}", file=sys.stderr)
        raise SystemExit(1) from error
